// Plantilla portable: IDs privados sólo en la instancia n8n. Sin IDs válidos no responde.
const CONFIG={owner_chat_id:"TODO_INSERT_KEY_HERE",owner_user_id:"TODO_INSERT_KEY_HERE"};
const m=$input.first().json.message;
if(!m||m.chat?.type!=='private'||!Number.isSafeInteger(m.chat.id)||!Number.isSafeInteger(m.from?.id)) return [];
const text=typeof m.text==='string'?m.text.trim():'';
if(String(m.chat.id)!==CONFIG.owner_chat_id||String(m.from.id)!==CONFIG.owner_user_id) return [];
const command=text.split(/\s+/)[0].split('@')[0].toLowerCase();
let reply;
if(command==='/start'||command==='/help') reply='Contracter · canal de mando\n/estado — estado del enlace\n/consulta — comprobación de preparación jurídica\n/auditar — comprobación de preparación de auditoría\nEste canal todavía no ejecuta dictámenes jurídicos ni aprueba contratos.';
else if(command==='/estado') reply='El enlace Telegram → n8n → Telegram funciona. Los flujos completos de auditoría siguen en modo MOCK. El corpus normativo y la ejecución LLM necesitan configuración y verificación antes de analizar contratos reales. Glenn se conserva en borrador por decisión del usuario.';
else if(command==='/consulta') reply='Consulta retenida: no hay corpus jurídico revisado enlazado a este flujo. No se afirmará vigencia ni se inventarán normas. La búsqueda y la respuesta legal permanecen deshabilitadas hasta verificar sus fuentes.';
else if(command==='/auditar') reply='Auditoría real retenida: los flujos 01 y 02 se probaron con un caso ficticio. Falta enlazar el proveedor LLM, la persistencia de cada intervención y el corpus jurídico revisado. No envíes contratos privados todavía.';
else reply='Usa /help para consultar los comandos. Los archivos y las aprobaciones contractuales no se aceptan en esta etapa.';
return [{json:{chat_id:String(m.chat.id),sender_id:String(m.from.id),reply}}];
